ROLE_CONFIG = "config/intelligence/role_intelligence.json"
BASE_CAPABILITIES = ["xmins","xmins_distribution","historical_prior","last_season_integration","prediction_quality_guard","small_sample_guard","projection_uncertainty","uncertainty_decomposition","team_attacking_strength","team_defensive_strength","opponent_defence_dynamic","clean_sheet_probability","fixture_context","fixture_swing","horizon_3","horizon_5","horizon_10","horizon_15","price_value","ownership_context","bonus_route","advanced_stats_integration","sustainability","team_defensive_risk","regression_risk","probabilistic_return_overlay","truthful_feature_bundle","tactical_matchup","observed_tactical_context","competitive_load","weather_shadow_research"]

def _capabilities(enrichment:dict[str,Any]|None=None)->list[str]:
    role_cfg=load_json_config(ROLE_CONFIG); enrichment_caps=enrichment.get("capabilities") if isinstance(enrichment,dict) else []; return sorted({*BASE_CAPABILITIES,*(str(x) for x in role_cfg.get("capabilities") or []),*(str(x) for x in enrichment_caps or [])})

def _quality_degraded_context(quality:dict[str,Any])->dict[str,Any]|None:
    if quality.get("status")=="HEALTHY":return None
    failed=[str(v) for v in quality.get("failed_checks") or []]; return {"service_id":"prediction","operation":"build","behavior":"prediction remains available for review but quality guard blocks unqualified GO","blocks_unqualified_go":True,"error_type":"PredictionQualityDegraded","error":",".join(failed) if failed else "prediction quality guard not healthy"}

def _source_fusion(payload:dict[str,Any])->dict[str,Any]:
    supplied=payload.get("source_fusion")
    if isinstance(supplied,dict):return supplied
    return {"status":"UNAVAILABLE","sources":{},"reason":"NOT_SUPPLIED_BY_ORCHESTRATOR","governance":{"fail_neutral":True,"missing_enrichment_is_unavailable_not_zero":True,"prediction_network_fetch_forbidden":True}}

def _observed_as_tactical_context(enrichment:dict[str,Any], supplied:dict[str,Any]|None)->dict[str,Any]:
    explicit=supplied if isinstance(supplied,dict) else {}; observed=enrichment.get("observed_tactical_context") if isinstance(enrichment.get("observed_tactical_context"),dict) else {}; observed_teams=observed.get("teams") if isinstance(observed.get("teams"),dict) else {}; team_profiles={}; recent_form={}
    for key,block in observed_teams.items():
        if not isinstance(block,dict):continue
        summary=block.get("summary") if isinstance(block.get("summary"),dict) else {}; recent=[row for row in block.get("recent") or [] if isinstance(row,dict)]; team_profiles[str(key)]={"team_id":int(key),"coach":None,"base_formation":summary.get("dominant_shape"),"formation_variants":summary.get("formation_variants") or [],"vulnerabilities":summary.get("vulnerabilities") or [],"strengths":summary.get("strengths") or [],"observed_style_proxies":summary.get("observed_style_proxies") or [],"pressing":None,"possession":None,"confidence":summary.get("confidence"),"evidence_class":"OBSERVED_MATCH_EVENT_AGGREGATE"}; recent_form[str(key)]=recent
    explicit_profiles=explicit.get("team_profiles") if isinstance(explicit.get("team_profiles"),dict) else {}; explicit_recent=explicit.get("recent_form") if isinstance(explicit.get("recent_form"),dict) else {}
    return {**explicit,"team_profiles":{**team_profiles,**explicit_profiles},"recent_form":{**recent_form,**explicit_recent},"observed_context_status":observed.get("status"),"observed_context_contract":observed.get("contract")}

def _compact_enrichment(enrichment:dict[str,Any])->dict[str,Any]:
    advanced=enrichment.get("advanced_stats") if isinstance(enrichment.get("advanced_stats"),dict) else {}; observed=enrichment.get("observed_tactical_context") if isinstance(enrichment.get("observed_tactical_context"),dict) else {}; load=enrichment.get("competitive_load") if isinstance(enrichment.get("competitive_load"),dict) else {}; schedule=enrichment.get("schedule") if isinstance(enrichment.get("schedule"),dict) else {}; preseason=enrichment.get("preseason") if isinstance(enrichment.get("preseason"),dict) else {}; current_form=enrichment.get("current_form") if isinstance(enrichment.get("current_form"),dict) else {}; fusion=enrichment.get("source_fusion") if isinstance(enrichment.get("source_fusion"),dict) else {}; fusion_sources=fusion.get("sources") if isinstance(fusion.get("sources"),dict) else {}; fusion_health=fusion.get("health") if isinstance(fusion.get("health"),dict) else {}; api_football=fusion_sources.get("api_football") if isinstance(fusion_sources.get("api_football"),dict) else {}; understat=fusion_sources.get("understat") if isinstance(fusion_sources.get("understat"),dict) else {}; api_observability=api_football.get("observability") if isinstance(api_football.get("observability"),dict) else {}; weather=enrichment.get("weather_shadow_research") if isinstance(enrichment.get("weather_shadow_research"),dict) else {}; weather_context=weather.get("weather_context") if isinstance(weather.get("weather_context"),dict) else {}; weather_health=enrichment.get("weather_health") if isinstance(enrichment.get("weather_health"),dict) else {}
    return {"status":enrichment.get("status"),"model":enrichment.get("model"),"advanced_stats":{k:advanced.get(k) for k in ("status","source","shots_rows","match_rows","coverage_players","missing_player_behavior","understat_status","understat_players")},"observed_tactical_context":{"status":observed.get("status"),"contract":observed.get("contract"),"team_count":len(observed.get("teams") or {}),"governance":observed.get("governance")},"competitive_load":{"status":load.get("status"),"contract":load.get("contract"),"planning_gw":load.get("planning_gw"),"player_count":load.get("player_count"),"state_counts":load.get("state_counts"),"players":load.get("players") or {},"governance":load.get("governance")},"weather_shadow_research":{"mode":weather.get("mode"),"Weather Context":weather_context.get("health"),"research_state":weather.get("research_state"),"severity":weather_context.get("severity"),"source_kind":weather_context.get("source_kind"),"decision_authority":weather_health.get("decision_authority","ZERO")},"schedule":{"status":schedule.get("status"),"european_competitions":sorted((schedule.get("european") or {}).keys()),"league_rest_team_count":len(schedule.get("league_rest_days") or {}),"cross_competition_rest_team_count":len(schedule.get("cross_competition_rest_days") or {}),"cross_competition_fixture_count":len(schedule.get("cross_competition_fixtures") or []),"domestic_cup_source":(schedule.get("domestic_cup") or {}).get("source"),"international_source":(schedule.get("international") or {}).get("source"),"api_football_status":api_football.get("status"),"governance":schedule.get("governance")},"preseason":preseason,"current_form":{"status":current_form.get("status"),"source":current_form.get("source"),"players":len(current_form.get("players") or {})},"source_fusion":{"status":fusion.get("status"),"season":fusion.get("season"),"health":fusion_health,"understat":{"status":understat.get("status"),"fetch_mode":understat.get("fetch_mode"),"player_count":understat.get("player_count",len(understat.get("players") or []))},"api_football":{"status":api_football.get("status"),"evidence_status":api_football.get("evidence_status"),"fixture_count":len(api_football.get("fixtures") or []),"resolved_competition_count":len([v for v in (api_football.get("resolved_competitions") or {}).values() if v]),"credential_present":api_observability.get("credential_present"),"network_requests":api_observability.get("network_requests"),"cache_hits":api_observability.get("cache_hits"),"quota_remaining":api_observability.get("quota_remaining"),"quota_limit":api_observability.get("quota_limit")}},"governance":enrichment.get("governance")}

def handle(operation:str,payload:dict[str,Any])->Any:
    if operation not in {"build","build_full","status"}:raise KeyError(f"unsupported prediction operation: {operation}")
    if operation=="status":return {"status":"ACTIVE","model_family":"P0_NATIVE_V5_HISTORICAL_PRIOR_ADVANCED_OVERLAY","bridge_only":False,"capabilities":_capabilities({"capabilities":["advanced_stats_sync","observed_tactical_context","competitive_load","european_congestion","domestic_cup_congestion","international_load","rest_days","preseason_prior","current_form","source_fusion","tactical_matchup","weather_shadow_research"]})}
    bootstrap=payload.get("bootstrap"); fixtures=payload.get("fixtures"); rules=payload.get("rules")
    if not isinstance(bootstrap,dict) or not isinstance(fixtures,list) or not isinstance(rules,dict):raise ValueError("prediction service requires bootstrap, fixtures and truth-service rules")
    planning_gw=int(payload.get("planning_gw") or 1); source_fusion=_source_fusion(payload); enrichment=build_full_core_enrichment(bootstrap,fixtures,source_fusion=source_fusion,planning_gw=planning_gw,competitive_load_observations=payload.get("competitive_load_observations") if isinstance(payload.get("competitive_load_observations"),dict) else None); weather_runtime=enrich_weather_shadow(payload.get("weather_evidence") if isinstance(payload.get("weather_evidence"),dict) else None); enrichment={**enrichment,"weather_shadow_research":weather_runtime["evidence"],"weather_health":{"Weather Context":weather_runtime["Weather Context"],"research_state":weather_runtime["research_state"],"decision_authority":weather_runtime["decision_authority"]}}; capabilities=_capabilities(enrichment); previous_prior=payload.get("historical_prior") if isinstance(payload.get("historical_prior"),dict) else {}; prior=resolve_prior(bootstrap,rules,previous_prior=previous_prior,allow_network_refresh=bool(payload.get("allow_historical_prior_refresh",False))); base=build_predictions(bootstrap,fixtures,rules,planning_gw,horizon=int(payload.get("horizon") or 15),historical_prior=prior); quality=evaluate_prediction_quality(base,prior,owned_ids=payload.get("owned_ids") or ()); degraded_context=_quality_degraded_context(quality); result=enrich_prediction({**base,"historical_prior_artifact":prior,"prediction_quality":quality,**({"degraded_context":degraded_context} if degraded_context else {})},enrichment); tactical_context=_observed_as_tactical_context(enrichment,payload.get("tactical_context") if isinstance(payload.get("tactical_context"),dict) else None); result=attach_tactical_matchups(result,planning_gw,tactical_context)
    if operation=="build_full":return {**result,"full_core_enrichment":enrichment,"capabilities":capabilities}
    compact=[]
    for player in result.get("players") or []:
        compact.append({"element":player["element"],"name":player.get("name"),"team_id":player.get("team_id"),"position":player.get("position"),"now_cost":player.get("now_cost"),"status":player.get("status"),"ownership_pct":player.get("ownership_pct"),"current_season":player.get("current_season"),"historical_prior":player.get("historical_prior"),"xmins":player.get("xmins"),"role":player.get("role"),"xpts_by_gw":player.get("xpts_by_gw"),"horizons":player.get("horizons"),"xpts_3":player.get("xpts_3"),"xpts_5":player.get("xpts_5"),"xpts_10":player.get("xpts_10"),"xpts_15":player.get("xpts_15"),"mean_xpts":player.get("mean_xpts"),"uncertainty":player.get("uncertainty"),"fixtures":player.get("fixtures"),"projection_confidence":player.get("projection_confidence"),"advanced":player.get("advanced"),"tactical_matchup":player.get("tactical_matchup")})
    return {"generated_at":result.get("generated_at"),"schema_version":result.get("schema_version"),"model_version":result.get("model_version"),"ruleset_id":result.get("ruleset_id"),"planning_gw":result.get("planning_gw"),"horizon_gws":result.get("horizon_gws"),"historical_prior":result.get("historical_prior"),"historical_prior_artifact":prior,"prediction_quality":quality,**({"degraded_context":degraded_context} if degraded_context else {}),"team_strength":result.get("team_strength"),"role_intelligence":result.get("role_intelligence"),"players":compact,"advanced_prediction":result.get("advanced_prediction"),"tactical_matchup_summary":result.get("tactical_matchup_summary"),"governance":result.get("governance"),"full_core_enrichment":_compact_enrichment(enrichment),"network_contract":result.get("network_contract"),"capabilities":capabilities}
